// Strict allowlist for the xb.ac2.stock_alert.v1 event from the AC2 stock export (#245).
// Anything outside the closed contract is rejected with a fixed reason code (HTTP 400 to the
// VM); nothing unvalidated reaches Telegram. Request headers are never read or passed on.
const items = $input.all();
const reject = (reason) => [{ json: { valid: false, reason } }];
if (items.length !== 1) return reject('AC2_ALERT_ITEM_COUNT');
const body = items[0].json && items[0].json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) return reject('AC2_ALERT_BODY');

const KEYS = ['schema', 'event', 'run_id', 'run_hour_local', 'alert_kind', 'status', 'failure_class', 'conditions', 'daily_close_status', 'delivery_status', 'feed_status', 'item_index_status', 'large_balance_count', 'late_change_day_count'];
const CONDITIONS = ['run_failed', 'daily_close_failed', 'delivery_failed', 'feed_failed', 'item_index_failed', 'large_balance', 'late_change'];
const KINDS = ['new', 'repeat'];
const FAILURE_CLASSES = ['config_invalid', 'timezone_unavailable', 'already_running', 'stale_lock', 'identity_refused', 'credential_unavailable', 'lock_timeout', 'unstable_snapshot', 'uom_guard', 'sync_read_failed', 'source_error', 'write_failed', 'latest_publish_failed', 'internal_error', 'ledger_mismatch', 'unknown'];
const CLOSE_STATUSES = ['not_due', 'published', 'failed', 'skipped_failed_run'];
const DELIVERY_STATUSES = ['not_configured', 'handed_to_drive_sync_folder', 'verify_failed', 'copy_failed', 'skipped_failed_run'];
const PUBLISH_STATUSES = ['published', 'failed'];
const COUNT_MAX = 1000000000;

const keys = Object.keys(body);
if (keys.length !== KEYS.length || !KEYS.every((key) => keys.includes(key))) return reject('AC2_ALERT_KEYS');
if (body.schema !== 'xb.ac2.stock_alert.v1') return reject('AC2_ALERT_SCHEMA');
if (body.event !== 'ac2_stock_alert') return reject('AC2_ALERT_EVENT');
if (typeof body.run_id !== 'string' || !/^([0-9a-f]{32}|unknown)$/.test(body.run_id)) return reject('AC2_ALERT_RUN_ID');
if (typeof body.run_hour_local !== 'string' || !/^\d{4}-\d\d-\d\dT\d\d:00:00[+-]\d\d:\d\d$/.test(body.run_hour_local)) return reject('AC2_ALERT_HOUR');
if (!KINDS.includes(body.alert_kind)) return reject('AC2_ALERT_KIND');
if (body.status !== 'success' && body.status !== 'failed') return reject('AC2_ALERT_STATUS');
const failed = body.status === 'failed';
if (failed ? !FAILURE_CLASSES.includes(body.failure_class) : body.failure_class !== null) return reject('AC2_ALERT_FAILURE_CLASS');
const conditions = body.conditions;
if (!Array.isArray(conditions) || conditions.length === 0 || conditions.length > CONDITIONS.length) return reject('AC2_ALERT_CONDITIONS');
if (new Set(conditions).size !== conditions.length || !conditions.every((c) => CONDITIONS.includes(c))) return reject('AC2_ALERT_CONDITIONS');
if (failed ? !(conditions.length === 1 && conditions[0] === 'run_failed') : conditions.includes('run_failed')) return reject('AC2_ALERT_CONDITIONS');
const oneOf = (value, allowed) => value === null || allowed.includes(value);
if (!oneOf(body.daily_close_status, CLOSE_STATUSES)) return reject('AC2_ALERT_CLOSE_STATUS');
if (!oneOf(body.delivery_status, DELIVERY_STATUSES)) return reject('AC2_ALERT_DELIVERY_STATUS');
if (!oneOf(body.feed_status, PUBLISH_STATUSES)) return reject('AC2_ALERT_FEED_STATUS');
if (!oneOf(body.item_index_status, PUBLISH_STATUSES)) return reject('AC2_ALERT_INDEX_STATUS');
for (const key of ['large_balance_count', 'late_change_day_count']) {
  if (!Number.isInteger(body[key]) || body[key] < 0 || body[key] > COUNT_MAX) return reject('AC2_ALERT_COUNTS');
}

const LABELS = {
  run_failed: 'Hourly export FAILED: ' + body.failure_class + ' (nothing new published this hour)',
  daily_close_failed: 'Daily close file not written (the next run retries)',
  delivery_failed: 'Drive delivery failed: ' + body.delivery_status,
  feed_failed: 'Dashboard feed not published',
  item_index_failed: 'Item index not published',
  large_balance: 'Large balances: ' + body.large_balance_count + ' row(s) above the threshold (check the AutoCount documents)',
  late_change: 'Late ledger changes: ' + body.late_change_day_count + ' day(s) older than the restate window',
};
const lines = [
  body.alert_kind === 'repeat' ? 'AC2 stock export: still not resolved (daily reminder)' : 'AC2 stock export: ERROR',
  '',
  ...CONDITIONS.filter((c) => conditions.includes(c)).map((c) => '- ' + LABELS[c]),
  '',
  'Hour: ' + body.run_hour_local.slice(0, 16).replace('T', ' ') + ' (UTC' + body.run_hour_local.slice(19) + ')',
  'Run: ' + body.run_id.slice(0, 8),
  'Details: last_run_status.json in the Drive folder; runbook section "Failure classes".',
];
return [{ json: { valid: true, alert_text: lines.join('\n') } }];
